(
  sum by (label_product, label_project) (
    kube_namespace_labels{label_project=~"$project", label_product=~"$product", label_environment_kind=~"$kind", cluster=~"$cluster", namespace=~"$namespace"} * on (cluster, namespace) group_right(label_environment_kind, label_project, label_product, label_client) (
      avg_over_time(
          namespace_cpu:kube_pod_container_resource_requests:sum{cluster=~"$cluster", namespace=~"$namespace"}[$range:1h]
      )
      or sum by (cluster, namespace, prometheus, prometheus_replica) (kube_namespace_labels{cluster=~"$cluster", namespace=~"$namespace"} * 0)
    )
  )

  - on (label_product, label_project)

  sum by (label_product, label_project) (
    kube_namespace_labels{label_project=~"$project", label_product=~"$product", label_environment_kind=~"$kind", cluster=~"$cluster", namespace=~"$namespace"} * on (cluster, namespace) group_right(label_environment_kind, label_project, label_product, label_client) (
      avg_over_time(
          namespace_cpu:kube_pod_container_resource_requests:sum{cluster=~"$cluster", namespace=~"$namespace"}[$range:1h] offset $offset
      )
      or sum by (cluster, namespace, prometheus, prometheus_replica) (kube_namespace_labels{cluster=~"$cluster", namespace=~"$namespace"} * 0)
    )
  )
)

